import math
    import random
    import time

    LANGUAGE_WRAPPER = "Consider the ellipse x^2/{a_axis}^2 + y^2/{b_axis}^2 = 1. An equilateral triangle is inscribed in this ellipse such that one vertex is at (0, {b_axis}) and the altitude from that vertex lies along the y-axis. Let s denote the side length of the triangle, and let c denote the y-coordinate of the triangle's center (which coincides with its centroid and circumcenter). If s^2 = m/n and c = u/v in lowest terms with m, n, u, v positive integers, determine m + n + u + v."

    class _RNGShim:
def __init__(self, seed: int):
    import random as _random
    self._seed = int(seed)
    self._r = _random.Random(self._seed)

def random(self): return self._r.random()
def uniform(self, a, b): return self._r.uniform(a, b)
def randint(self, a, b): return self._r.randint(a, b)
def randrange(self, *args): return self._r.randrange(*args)
def choice(self, seq): return self._r.choice(seq)
def choices(self, population, weights=None, cum_weights=None, k: int = 1):
    return self._r.choices(population, weights=weights, cum_weights=cum_weights, k=k)
def sample(self, population, k: int): return self._r.sample(population, k)
def shuffle(self, x):
    self._r.shuffle(x)
    return x
def getrandbits(self, k: int): return self._r.getrandbits(k)

    def generator(rng):
import math
# We seek b_axis > a_axis so c > 0; also ensure s^2 not integer and answer large enough.
for _ in range(1000):
    a = rng.randint(2, 18)
    b = rng.randint(a + 1, 26)
    # s^2 = 48 a^4 b^2 / (b^2 + 3 a^2)^2
    s2_num0 = 48 * (a ** 4) * (b ** 2)
    s2_den0 = (b ** 2 + 3 * a ** 2) ** 2
    g1 = math.gcd(s2_num0, s2_den0)
    m = s2_num0 // g1
    n = s2_den0 // g1
    # c = b (b^2 - a^2) / (b^2 + 3 a^2)
    c_num0 = b * (b ** 2 - a ** 2)
    c_den0 = b ** 2 + 3 * a ** 2
    if c_num0 <= 0:
        continue  # want positive c
    g2 = math.gcd(c_num0, c_den0)
    u = c_num0 // g2
    v = c_den0 // g2
    total = m + n + u + v
    # Enforce non-triviality: s^2 not integer and answer sufficiently large
    if n <= 1:
        continue
    if total < 180:
        continue
    return {"a_axis": a, "b_axis": b}
# Fallback deterministic choice guaranteed to satisfy constraints
a = 8
b = 15
return {"a_axis": a, "b_axis": b}

